// This file generated by Claude, and slightly edited
//
// Molecular skin surface (Edelsbrunner, "Deformable Smooth Surface Design") ->
// trimmed parametric surfaces in STEP (ISO 10303-21, AP214).
//
// A skin surface is the union of patches, one per cell of the mixed complex.
// Each patch is  (quadric) ∩ (convex polytope):
//
//   vertex / tetrahedron cell : sphere            |p - c|^2 = r^2
//   edge cell                 : hyperboloid, 1 sheet   rho^2 - B z^2 = A, A > 0
//   triangle cell             : hyperboloid, 2 sheets  rho^2 - B z^2 = A, A < 0
//
// where z = axis . (p - c) and rho is the distance to the axis line (for the
// skin surface B == 1, the axis is the Delaunay edge direction resp. the
// triangle normal; the general B > 0 is supported anyway).
//
// Every quadric is written as an exact STEP parametric surface
//   SPHERICAL_SURFACE    (u,v) -> c + r(cos v (cos u X + sin u Y) + sin v Z)
//   SURFACE_OF_REVOLUTION (HYPERBOLA)
//                        (u,v) -> rotate_axis(u) . (C + a cosh v X + b sinh v Y)
// and trimmed by exact conics (CIRCLE / ELLIPSE / HYPERBOLA / PARABOLA), which
// are the intersections of the quadric with the planes of the polytope.
// The topology is a proper B-rep: ADVANCED_FACE -> FACE_BOUND -> EDGE_LOOP ->
// ORIENTED_EDGE -> EDGE_CURVE -> VERTEX_POINT.

#pragma once
#include <geogram/basic/geometry.h>
#include <geogram/basic/memory.h>
#include <vector>
#include <string>

namespace MSS_Claude {
    using namespace GEO;

    /************************************************************************/

    class StepWriter {
    public:
	explicit StepWriter(double tol = 1e-7) : tol_(tol) {
	}

	double tol() const {
	    return tol_;
	}

	int add(const std::string& body);
	void add_face(int face_id);
	std::string real(double v) const;
	static std::string ref(int id);
	static std::string refs(const std::vector<int>& ids);
	int point(const vec3& p);
	int direction(const vec3& d);
	int axis2(const vec3& o, const vec3& z, const vec3& x);
	int axis1(const vec3& o, const vec3& z);
	// Writes all collected faces as one open shell. Call once.
	bool save(
	    const std::string& path, const std::string& name = "molecular_skin"
	);

    private:
	double tol_;
	std::vector<std::string> entities_;
	std::vector<int> faces_;
    };

    /************************************************************************/

    // Half-space  n . p <= d  (n need not be unit).
    struct HalfSpace {
	vec3 n;
	double d;
    };

    struct SpherePatch {
	vec3 center;
	double radius;
	std::vector<HalfSpace> cell;     // the mixed cell (convex polytope)
	// true  : the solid is the ball   |p-c|^2 <= r^2        (vertex cells)
	// false : the solid is its complement              (tetrahedron cells)
	bool solid_is_inside = true;
    };

    struct HyperboloidPatch {
	vec3 center;          // point on the axis, center of symmetry
	vec3 axis;            // axis direction (normalized internally)
	double A;             // rho^2 - B z^2 = A ;  A>0: 1 sheet, A<0: 2 sheets
	double B = 1.0;       // > 0 (== 1 for skin surfaces)
	std::vector<HalfSpace> cell;
	// true  : the solid is  rho^2 - B z^2 <= A  (edge cells)
	// false : the solid is  rho^2 - B z^2 >= A  (triangle cells)
	bool solid_is_inside = true;
    };

    /************************************************************************/
    // Sphere ∩ convex cell -> trimmed SPHERICAL_SURFACE faces
    // (one per octant met).
    bool sphere_patch_to_step(const SpherePatch& P, StepWriter& w);

    // Hyperboloid of revolution ∩ convex cell -> trimmed rational Bezier faces.
    bool hyperboloid_patch_to_step(const HyperboloidPatch& P, StepWriter& w);

    /*************************************************************************/
}
